import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.CNDaxUod.js";const m=JSON.parse('{"title":"Roles and permissions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/roles.md","filePath":"guide/roles.md"}'),r={name:"guide/roles.md"};function s(n,t,i,h,c,l){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="roles-and-permissions" tabindex="-1">Roles and permissions <a class="header-anchor" href="#roles-and-permissions" aria-label="Permalink to &quot;Roles and permissions&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Role</th><th>How you get it</th><th>What it grants</th></tr></thead><tbody><tr><td>Operator</td><td>Holds the operator token (<code>OPERATOR_TOKEN</code>)</td><td>Everything, including workspace settings, while token sign-in is on</td></tr><tr><td>Workspace admin</td><td>A Google Workspace super or delegated admin (through the <a href="./directory.html">Directory</a>), in the SAML admin group, or granted Admin</td><td>The full console: every standup, workspace settings, deleting archived standups</td></tr><tr><td>Manager (standup admin)</td><td>Ran <code>setup</code>, created the standup in the web app, was granted <code>admin @user</code>, or granted Manager</td><td>Configure that standup from Chat or the web app; manage the schedules and time-off requests of people on it</td></tr><tr><td>Viewer</td><td>Granted Viewer, on one standup or across the workspace</td><td>Read standups, answers, blockers and reports, see the team, and export. No changes</td></tr><tr><td>Custom role</td><td>Granted a role your admins made</td><td>The permissions that role holds</td></tr><tr><td>Participant</td><td>On the standup&#39;s roster: picked in the People grid, <code>add @user</code>, or a member of the Google Group it follows</td><td>Answer, edit, skip, DM self-service, their own page at <code>/app/me</code></td></tr><tr><td>Everyone in the space</td><td>—</td><td><code>status</code>, <code>trends</code>, <code>blockers</code>, <code>blocker</code>, polls, <code>help</code>, and <code>setup</code></td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Every check in the web app, the <a href="./api.html">JSON API</a>, Chat commands and <a href="./mcp.html">MCP</a> asks for one permission, either across the workspace or on one standup. The roles above are fixed sets of them:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Lets you</th><th>Admin</th><th>Manager</th><th>Viewer</th><th>Participant</th></tr></thead><tbody><tr><td><code>standups.view</code></td><td>See a standup, who is on it and how today is going</td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>answers.view</code></td><td>Read each day&#39;s answers</td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>blockers.view</code></td><td>See blockers and their updates</td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>reports.view</code></td><td>See run history and insights</td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>people.view</code></td><td>See the Team directory</td><td>✓</td><td>✓</td><td>✓</td><td></td></tr><tr><td><code>export</code></td><td>Download answers as CSV</td><td>✓</td><td>✓</td><td>✓</td><td></td></tr><tr><td><code>standups.configure</code></td><td>Change the schedule, questions, mood, escalation and webhook; run now, nudge, close polls</td><td>✓</td><td>✓</td><td></td><td></td></tr><tr><td><code>standups.archive</code></td><td>Archive a standup and bring it back</td><td>✓</td><td>✓</td><td></td><td></td></tr><tr><td><code>people.manage</code></td><td>Add and remove people, mark them required, make managers</td><td>✓</td><td>✓</td><td></td><td></td></tr><tr><td><code>schedules.manage</code></td><td>Change people&#39;s weeks and days off, decide time-off requests</td><td>✓</td><td>✓</td><td></td><td></td></tr><tr><td><code>blockers.manage</code></td><td>Resolve anyone&#39;s blocker</td><td>✓</td><td>✓</td><td></td><td></td></tr><tr><td><code>standups.create</code></td><td>Create standups from the web app or API</td><td>✓</td><td></td><td></td><td></td></tr><tr><td><code>standups.delete</code></td><td>Delete an archived standup with its history</td><td>✓</td><td></td><td></td><td></td></tr><tr><td><code>settings.manage</code></td><td>Workspace settings, setup checks, deleting history</td><td>✓</td><td></td><td></td><td></td></tr><tr><td><code>sso.manage</code></td><td>Google sign-in, SAML and token sign-in</td><td>✓</td><td></td><td></td><td></td></tr><tr><td><code>tokens.manage</code></td><td>Machine tokens, service MCP tokens, everyone&#39;s MCP tokens</td><td>✓</td><td></td><td></td><td></td></tr><tr><td><code>roles.manage</code></td><td>Create roles, grant them, and set the SAML admin group</td><td>✓</td><td></td><td></td><td></td></tr></tbody></table><p>A participant&#39;s permissions apply only to their own standups, and a manager&#39;s to the standups they manage. The API reference names the permission each route needs. Anonymous moods stay anonymous for every role.</p><h2 id="custom-roles-and-grants" tabindex="-1">Custom roles and grants <a class="header-anchor" href="#custom-roles-and-grants" aria-label="Permalink to &quot;Custom roles and grants&quot;">​</a></h2><p>A <strong>custom role</strong> is a name and a set of the permissions above. A <strong>grant</strong> gives a role to someone, by email, either across the workspace or on one standup. Built-in roles (Admin, Manager, Viewer, Member) can&#39;t be changed; Member comes from being on a roster, so it isn&#39;t granted.</p><table tabindex="0"><thead><tr><th>Rule</th><th>Why</th></tr></thead><tbody><tr><td>You can only put permissions you hold into a role, and only grant or revoke a role whose permissions you hold at that scope</td><td>Nobody can hand themselves or others more than they have</td></tr><tr><td>Granting across the workspace needs <code>roles.manage</code>. On one standup, managing its people (<code>people.manage</code>) is enough</td><td>Managers can bring in a Viewer for their own standup</td></tr><tr><td>A role with a workspace-only permission can only be granted across the workspace</td><td>Those permissions have no meaning on one standup</td></tr><tr><td>A custom role with any standup permission also gets <code>standups.view</code></td><td>The others work on a standup the holder can see</td></tr><tr><td>You can&#39;t revoke or edit away your own <code>roles.manage</code></td><td>Someone else, or the operator token, has to. Admins through Google or SAML are never locked out</td></tr><tr><td>A role that anyone holds can&#39;t be deleted</td><td>Revoke its grants first</td></tr></tbody></table><p>Grants follow a person&#39;s email. Google and SAML sign-ins carry it, and in Chat it&#39;s the email AsyncUp has learned for that person (from the <a href="./directory.html">Directory</a> or their first interaction). Changes apply on the next request; an MCP token follows its owner&#39;s roles as they are now.</p><p>Every change to a role or grant is logged with who made it and when. Manage them through the <a href="./api.html">JSON API</a>: <code>GET /api/v1/permissions</code>, <code>/api/v1/roles</code>, <code>/api/v1/grants</code> and <code>GET /api/v1/roles/audit</code>.</p><p>Notes:</p><ul><li>A standup always keeps at least one admin; removing the last is refused.</li><li>A standup created with no admins (for example from a script with the operator token) is open to configuration by anyone in its space. Name an admin when creating on someone&#39;s behalf.</li><li>The web app and the <a href="./api.html">JSON API</a> share one authorisation model. MCP tools act as the token&#39;s owner and see exactly what that person sees (<a href="./mcp.html">Claude Code and MCP</a>).</li><li>Who may mark someone away is set per standup by its <a href="./schedules.html#who-can-change-what-the-time-off-policy">time-off policy</a>.</li></ul>',13)])])}const u=e(r,[["render",s]]);export{m as __pageData,u as default};
